import {initDesignerUI, enhanceInspector, questionPreview, previewDraftLabels, enhanceChoiceLists} from "./ui.js";
import {rowsFromTable,sortByOrder,codeOf} from "../shared/grist-common.js";
import {readWorkbook,writeWorkbook} from "./xlsx-lite.js";
// Fetch persisted answers again before destructive definition batches, including imports.
async function applyDesignerActions(actions){
 const removed=actions.filter(a=>a[0]==="RemoveRecord"&&["QUESTIONS","CHOIX_QUESTIONS","COLONNES_MATRICE"].includes(a[1]));
 if(removed.length){
  let values,selections;
  try{[values,selections]=await Promise.all(["VALEURS_REPONSE","SELECTIONS_REPONSE"].map(async t=>rowsFromTable(await grist.docApi.fetchTable(t))))}
  catch{throw new Error("Suppression bloquée : impossible de vérifier les réponses enregistrées. Réessayez plus tard.")}
  const match=(raw,row,key)=>String(codeOf(raw))===String(row.id)||String(codeOf(raw))===String(codeOf(row[key]));
  for(const [,table,id] of removed){
   const key=table==="QUESTIONS"?"Question_Code":table==="CHOIX_QUESTIONS"?"Choix_Code":"ColonneMatrice_Code",row=(S.data[table]||[]).find(r=>String(r.id)===String(id));
   if(!row)throw new Error("Suppression bloquée : définition introuvable, rechargez le concepteur.");
   let used=false;
   if(table==="QUESTIONS"){const qs=[row,...(S.data.QUESTIONS||[]).filter(q=>match(q.Question_parente_Code,row,key))];used=values.some(v=>qs.some(q=>match(v.Question_Code,q,key)))}
   else if(table==="COLONNES_MATRICE")used=values.some(v=>match(v.ColonneMatrice_Code,row,key));
   else{const owner=(S.data.QUESTIONS||[]).find(q=>match(row.Question_Code,q,"Question_Code")),qs=owner?[owner,...(S.data.QUESTIONS||[]).filter(q=>match(q.Question_parente_Code,owner,"Question_Code"))]:[];used=selections.some(v=>match(v.Choix_Code,row,key))||values.some(v=>qs.some(q=>match(v.Question_Code,q,"Question_Code"))&&String(v.Valeur_texte??"")===String(codeOf(row.Choix_Code)))}
   if(used)throw new Error("Suppression bloquée : cet élément est utilisé par une réponse enregistrée. Désactivez-le pour conserver l’historique.");
  }
 }
 return grist.docApi.applyUserActions(actions);
}
function confirmDraftDiscard(){const f=$("#edit-form");if(f?.dataset?.dirty!=="1")return true;if(!confirm("Des modifications ne sont pas enregistrées. Les abandonner et continuer ?"))return false;f.dataset.dirty="0";return true}
const TABLES=["QUESTIONNAIRES","VERSIONS_QUESTIONNAIRES","PAGES","SECTIONS","QUESTIONS","TYPES_FICHES","FILTRES_TYPES_FICHES","CHOIX_QUESTIONS","REFERENTIELS","VALEURS_REFERENTIELS","STRUCTURES","CONDITIONS","REGLES_CONDITION","FILTRES_CHOIX","COLONNES_MATRICE","CAMPAGNES"];
const S={data:{},questionnaire:null,version:null,selected:null,showInactive:false,resultsExportData:null};
function rememberRespondentPreview(){try{if(S.version)localStorage.setItem("gristionnaire.previewVersion",String(S.version));else localStorage.removeItem("gristionnaire.previewVersion");if(S.questionnaire)localStorage.setItem("gristionnaire.previewQuestionnaire",String(S.questionnaire));}catch{}}
const $=s=>document.querySelector(s);
const isTrue=v=>v===true||v===1||String(v??"").toLowerCase()==="true";
const esc=(v="")=>String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const active=r=>{const v=Object.prototype.hasOwnProperty.call(r||{},"Actif")?r.Actif:r?.Active;return v===undefined||v===null||v===""||v===true||v===1||String(v).toLowerCase()==="true"};
const first=(r,n,f="")=>{for(const k of n)if(r?.[k]!=null&&r[k]!=="")return r[k];return f};
const field=(r,n)=>n.find(k=>Object.prototype.hasOwnProperty.call(r||{},k))||null;
function ref(v,rows,col){const x=codeOf(v);if(!x)return "";const r=(rows||[]).find(a=>String(a.id)===String(x));return r?codeOf(r[col]):x}
function label(r,t){if(t==="page")return first(r,["Titre","Nom","Libelle","Page_Code"],codeOf(r.Page_Code));if(t==="section")return first(r,["Titre","Nom","Libelle","Section_Code"],codeOf(r.Section_Code));if(t==="fiche")return first(r,["Libelle_singulier","Libelle","Nom","TypeFiche_Code"],codeOf(r.TypeFiche_Code));if(t==="question")return first(r,["Libelle","Libellé","Question","Titre","Question_Code"],codeOf(r.Question_Code));if(t==="questionnaire")return first(r,["Nom","Titre","Questionnaire_Code"],codeOf(r.Questionnaire_Code));return first(r,["Nom","Libelle","Titre","Version_Code"],codeOf(r.Version_Code))}
async function reload(){for(const t of TABLES)S.data[t]=rowsFromTable(await grist.docApi.fetchTable(t));renderSelectors()}
const qForV=v=>ref(v.Questionnaire_Code,S.data.QUESTIONNAIRES,"Questionnaire_Code");
const versions=()=>S.data.VERSIONS_QUESTIONNAIRES.filter(v=>!S.questionnaire||qForV(v)===S.questionnaire);
const questionnaireRow=()=>S.data.QUESTIONNAIRES.find(q=>codeOf(q.Questionnaire_Code)===S.questionnaire);
function writableCloneKeys(row){return new Set(Object.keys(row||{}).filter(k=>k!=="id"&&!String(k).startsWith("gristHelper_")))}
function setIfSupported(values,sample,names,value){const k=field(sample,names);if(k&&value!==undefined)values[k]=value;return k}
async function ensureQuestionnaireDisplayColumns(){const sample=S.data.VERSIONS_QUESTIONNAIRES[0]||{},actions=[];const specs=[["Titre",["Titre","Titre_affiche"],"Text"],["Introduction",["Introduction","Texte_introduction"],"Text"],["Logo_URL",["Logo_URL","Logo","Url_logo"],"Text"],["Logo_Data",["Logo_Data"],"Text"],["Logo_Taille",["Logo_Taille"],"Text"],["Logo_Alignement",["Logo_Alignement"],"Text"],["Pied_de_page",["Pied_de_page","Pied_page","Footer"],"Text"],["Afficher_sommaire",["Afficher_sommaire","Sommaire"],"Bool"],["Mode_sommaire",["Mode_sommaire"],"Text"],["Afficher_progression",["Afficher_progression","Afficher_barre_progression","Barre_progression"],"Bool"]];for(const [name,aliases,type] of specs)if(!field(sample,aliases))actions.push(["AddColumn","VERSIONS_QUESTIONNAIRES",name,{type}]);if(actions.length){await applyDesignerActions(actions);await reload()}}
async function createQuestionnaire(fd){
 const name=String(fd.get("internal-name")||"").trim();if(!name)throw new Error("Le nom interne est obligatoire.");
 const title=String(fd.get("display-title")||"").trim();const intro=String(fd.get("introduction")||"").trim();const logo="";const footer=String(fd.get("footer")||"").trim();const tocMode=String(fd.get("toc-mode")||"desactive");const toc=tocMode!=="desactive";
 await ensureQuestionnaireDisplayColumns();const qSample=S.data.QUESTIONNAIRES[0]||{},vSample=S.data.VERSIONS_QUESTIONNAIRES[0]||{};const qCode=unique("QUESTIONNAIRE"),vCode=unique("VERSION");
 const qValues={Questionnaire_Code:qCode};setIfSupported(qValues,qSample,["Nom","Titre","Libelle"],name);if(field(qSample,["Active","Actif"]))qValues[field(qSample,["Active","Actif"])]=true;
 await applyDesignerActions([["AddRecord","QUESTIONNAIRES",null,qValues]]);await reload();
 const createdQ=(S.data.QUESTIONNAIRES||[]).find(q=>codeOf(q.Questionnaire_Code)===qCode);if(!createdQ)throw new Error("Questionnaire créé mais introuvable après relecture.");
 const vValues={Version_Code:vCode,Questionnaire_Code:Number(createdQ.id)};setIfSupported(vValues,vSample,["Nom"],"Version 1");setIfSupported(vValues,vSample,["Titre","Titre_affiche"],title||name);setIfSupported(vValues,vSample,["Introduction","Texte_introduction"],intro);setIfSupported(vValues,vSample,["Logo_URL","Logo","Url_logo"],logo);setIfSupported(vValues,vSample,["Pied_de_page","Pied_page","Footer"],footer);setIfSupported(vValues,vSample,["Afficher_sommaire","Sommaire"],toc);setIfSupported(vValues,vSample,["Mode_sommaire"],tocMode);setIfSupported(vValues,vSample,["Afficher_progression","Afficher_barre_progression","Barre_progression"],true);if(field(vSample,["Active","Actif"]))vValues[field(vSample,["Active","Actif"])]=true;
 await applyDesignerActions([["AddRecord","VERSIONS_QUESTIONNAIRES",null,vValues]]);await reload();
 const createdV=(S.data.VERSIONS_QUESTIONNAIRES||[]).find(v=>codeOf(v.Version_Code)===vCode);if(!createdV)throw new Error("Première version créée mais introuvable après relecture.");
 S.questionnaire=qCode;S.version=vCode;S.selected=null;renderSelectors();status("Questionnaire créé. Vous pouvez maintenant ajouter sa première page.",false,true);
}
