// État purement visuel de l'arborescence : aucune modification des données Grist.
const collapsedTreeNodes=new Set();
function treeNodeDepth(el){
 if(el.dataset.type==="page")return 0;
 if(el.dataset.type==="section")return 1;
 if(el.dataset.type==="fiche")return el.classList.contains("subfiche")?3:2;
 if(el.classList.contains("subfiche-question"))return 4;
 if(el.classList.contains("fiche-question"))return 3;
 return 2;
}
function treeCollapseKey(el){return `${S.version||""}:${el.dataset.type}:${el.dataset.id}`}
function bindTreeCollapse(){
 const root=$("#tree"),items=[...root.querySelectorAll(":scope > .tree-item")];
 // Construire de vrais conteneurs descendants, plutôt que masquer séparément
 // chaque ligne d'une liste plate (fragile avec les styles du Concepteur).
 const fragment=document.createDocumentFragment(),stack=[];
 const heading=root.querySelector(".tree-orphans-heading");
 for(const el of items){
  const orphan=el.classList.contains("tree-orphan");
  const depth=orphan?0:treeNodeDepth(el);
  if(orphan){
   stack.length=0;
   if(heading&&heading.parentElement===root)fragment.appendChild(heading);
  }
  while(stack.length&&stack[stack.length-1].depth>=depth)stack.pop();
  const parent=stack.length?stack[stack.length-1].children:fragment;
  const node=document.createElement("div");
  node.className="tree-node";
  node.appendChild(el);
  parent.appendChild(node);
  if(!orphan&&["page","section","fiche"].includes(el.dataset.type)){
   const children=document.createElement("div");
   children.className="tree-node-children";
   node.appendChild(children);
   const key=treeCollapseKey(el);
   const toggle=document.createElement("button");
   toggle.type="button";
   toggle.className="tree-collapse-toggle";
   toggle.dataset.collapseKey=key;
   toggle.onclick=(event)=>{
    event.stopPropagation();
    if(collapsedTreeNodes.has(key))collapsedTreeNodes.delete(key);
    else collapsedTreeNodes.add(key);
    renderTree();
   };
   node.insertBefore(toggle,children);
   const collapsed=collapsedTreeNodes.has(key);
   toggle.textContent=collapsed?"▸":"▾";
   toggle.title=collapsed?"Déplier les éléments":"Replier les éléments";
   toggle.setAttribute("aria-label",toggle.title);
   toggle.setAttribute("aria-expanded",String(!collapsed));
   children.hidden=collapsed;
   children.style.display=collapsed?"none":"";
   stack.push({depth,children});
  }
 }
 root.appendChild(fragment);
 // Supprimer les chevrons inutiles sur les conteneurs sans descendants.
 root.querySelectorAll(".tree-node-children").forEach(children=>{
  if(children.childElementCount)return;
  const node=children.parentElement;
  node.querySelector(":scope > .tree-collapse-toggle")?.remove();
  children.remove();
 });
}
function renderTree(){const {pages,sections,questions,fiches}=current();let h="";for(const p of pages){const pc=codeOf(p.Page_Code);h+=item("page",p,label(p,"page"),"tree-page");for(const s of sections.filter(x=>ref(x.Page_Code,S.data.PAGES,"Page_Code")===pc)){const sc=codeOf(s.Section_Code);h+=item("section",s,label(s,"section"),"tree-section");const sq=questions.filter(q=>ref(q.Section_Code,S.data.SECTIONS,"Section_Code")===sc);for(const q of sq.filter(q=>!isMatrixLine(q)&&!ref(q.TypeFiche_Code,fiches,"TypeFiche_Code")))h+=item("question",q,label(q,"question"),"tree-question");const ft=new Set(sq.map(q=>ref(q.TypeFiche_Code,fiches,"TypeFiche_Code")).filter(Boolean));const parents=fiches.filter(f=>!isSubFiche(f)&&(ft.has(codeOf(f.TypeFiche_Code))||fiches.some(sf=>ficheParentCode(sf)===codeOf(f.TypeFiche_Code)&&ft.has(codeOf(sf.TypeFiche_Code)))));for(const f of parents){h+=item("fiche",f,label(f,"fiche"),"tree-fiche");const fc=codeOf(f.TypeFiche_Code);for(const q of sq.filter(q=>!isMatrixLine(q)&&ref(q.TypeFiche_Code,fiches,"TypeFiche_Code")===fc))h+=item("question",q,label(q,"question"),"tree-question fiche-question");for(const sf of fiches.filter(x=>ficheParentCode(x)===fc)){h+=item("fiche",sf,label(sf,"fiche"),"tree-fiche subfiche");const sfc=codeOf(sf.TypeFiche_Code);for(const q of sq.filter(q=>!isMatrixLine(q)&&ref(q.TypeFiche_Code,fiches,"TypeFiche_Code")===sfc))h+=item("question",q,label(q,"question"),"tree-question fiche-question subfiche-question")}}}}
 // Sécurité d'affichage : une question de la version courante ne doit jamais être
 // inaccessible parce que son rattachement ne correspond pas aux filtres imbriqués.
 // Les questions déjà affichées restent à leur emplacement habituel.
 const shownQuestionIds=new Set([...h.matchAll(/data-type="question" data-id="(\d+)"/g)].map(m=>m[1]));
 // Retrouver l'emplacement avec les références réelles, sans dépendre de
 // l'existence d'une autre question visible dans la même fiche.
 // Une fiche sans question initialement classée n'était jamais créée par le
 // parcours ci-dessus : on l'affiche sous la section de sa question.
 const unmatchedFicheQuestions=questions.filter(q=>!isMatrixLine(q)&&!shownQuestionIds.has(String(q.id))&&ref(q.TypeFiche_Code,fiches,"TypeFiche_Code"));
 for(const q of unmatchedFicheQuestions){
  const ficheCode=ref(q.TypeFiche_Code,fiches,"TypeFiche_Code");
  const fiche=fiches.find(f=>codeOf(f.TypeFiche_Code)===ficheCode);
  const sectionCode=ref(q.Section_Code,S.data.SECTIONS,"Section_Code");
  const section=sections.find(sec=>codeOf(sec.Section_Code)===sectionCode);
  if(!fiche||!section)continue; // Conserver l'avertissement si références invalides.
  const sectionMarker=`data-type="section" data-id="${section.id}"`;
  const sectionPos=h.indexOf(sectionMarker);
  if(sectionPos<0)continue; // La page de la section n'est pas visible.
  const ficheMarker=`data-type="fiche" data-id="${fiche.id}"`;
  let fichePos=h.indexOf(ficheMarker,sectionPos);
  // Ne pas réutiliser une fiche affichée sous une autre section.
  const nextSection=h.indexOf('data-type="section"',sectionPos+sectionMarker.length);
  if(fichePos<0||(nextSection>=0&&fichePos>nextSection)){
   const parentCode=ficheParentCode(fiche);
   const parent=fiches.find(f=>codeOf(f.TypeFiche_Code)===parentCode);
   const sectionEnd=h.indexOf('</button>',sectionPos);
   if(sectionEnd<0)continue;
   let position=sectionEnd+'</button>'.length;
   // Pour une sous-fiche, rétablir aussi sa fiche parente si nécessaire.
   if(parent){
    const parentMarker=`data-type="fiche" data-id="${parent.id}"`;
    let parentPos=h.indexOf(parentMarker,sectionPos);
    if(parentPos<0||(nextSection>=0&&parentPos>nextSection)){
     const parentHtml=item("fiche",parent,label(parent,"fiche"),"tree-fiche tree-recovered");
     h=h.slice(0,position)+parentHtml+h.slice(position);
     position+=parentHtml.length;
    }else{
     const parentEnd=h.indexOf('</button>',parentPos);
     position=parentEnd+'</button>'.length;
    }
   }
   const ficheHtml=item("fiche",fiche,label(fiche,"fiche"),`tree-fiche ${parent?"subfiche ":""}tree-recovered`);
   h=h.slice(0,position)+ficheHtml+h.slice(position);
   fichePos=position;
  }
  const ficheEnd=h.indexOf('</button>',fichePos);
  if(ficheEnd<0)continue;
  const insertion=ficheEnd+'</button>'.length;
  h=h.slice(0,insertion)+item("question",q,label(q,"question"),`tree-question fiche-question ${isSubFiche(fiche)?"subfiche-question ":""}tree-recovered`)+h.slice(insertion);
  shownQuestionIds.add(String(q.id));
 }
 const unmatched=questions.filter(q=>!isMatrixLine(q)&&!shownQuestionIds.has(String(q.id)));
 if(unmatched.length){h+=`<div class="tree-orphans-heading" role="note">Questions sans emplacement visible (${unmatched.length}) — rattachement à vérifier</div>`;for(const q of unmatched)h+=item("question",q,label(q,"question"),"tree-question tree-orphan")}
 $("#tree").innerHTML=h||'<div class="empty-state">Aucune page.</div>';document.querySelectorAll("#tree .tree-item").forEach(b=>b.onclick=()=>select(b.dataset.type,b.dataset.id));bindTreeCollapse();bindTreeDragDrop()}
const rows=t=>({page:S.data.PAGES,section:S.data.SECTIONS,question:S.data.QUESTIONS,fiche:S.data.TYPES_FICHES}[t]||[]);

let treeDrag=null;
let treeDragPointerY=null;
let treeDragScrollFrame=null;
function dragSiblings(type,row){
 const {pages,sections,questions}=current();
 if(type==="page")return pages;
 if(type==="section")return sections.filter(x=>String(x.Page_Code)===String(row.Page_Code));
 if(type==="question"){const fiche=ref(row.TypeFiche_Code,S.data.TYPES_FICHES,"TypeFiche_Code")||"";return questions.filter(q=>!isMatrixLine(q)&&String(q.Section_Code)===String(row.Section_Code)&&String(ref(q.TypeFiche_Code,S.data.TYPES_FICHES,"TypeFiche_Code")||"")===String(fiche))}
 return [];
}
function isMainTreeQuestion(row){return Boolean(row)&&!isMatrixLine(row)&&!ref(row.TypeFiche_Code,S.data.TYPES_FICHES,"TypeFiche_Code")}
function pageForSection(section){return S.data.PAGES.find(p=>String(p.id)===String(codeOf(section?.Page_Code)||section?.Page_Code))||null}
function sectionForQuestion(question){return S.data.SECTIONS.find(s=>String(s.id)===String(codeOf(question?.Section_Code)||question?.Section_Code))||null}
function treeDropPlan(drag,targetType,target){
 const source=rows(drag.type).find(x=>String(x.id)===String(drag.id));
 if(!source||!target||String(source.id)===String(target.id)&&drag.type===targetType)return null;
 if(drag.type==="page"&&targetType==="page")return {kind:"reorder",type:"page",source,target};
 if(drag.type==="section"){
  if(targetType==="page")return {kind:"move-section",source,targetPage:target,targetSection:null};
  if(targetType==="section")return String(source.Page_Code)===String(target.Page_Code)?{kind:"reorder",type:"section",source,target}:{kind:"move-section",source,targetPage:pageForSection(target),targetSection:target};
 }
 if(drag.type==="question"){
  const sourceFiche=ref(source.TypeFiche_Code,S.data.TYPES_FICHES,"TypeFiche_Code")||"";
  if(sourceFiche){
   if(targetType!=="question")return null;
   const targetFiche=ref(target.TypeFiche_Code,S.data.TYPES_FICHES,"TypeFiche_Code")||"";
   return sourceFiche===targetFiche&&String(source.Section_Code)===String(target.Section_Code)?{kind:"reorder",type:"question",source,target}:null;
  }
  if(targetType==="section")return {kind:"move-question",source,targetSection:target,targetQuestion:null};
  if(targetType==="question"&&isMainTreeQuestion(target))return String(source.Section_Code)===String(target.Section_Code)?{kind:"reorder",type:"question",source,target}:{kind:"move-question",source,targetSection:sectionForQuestion(target),targetQuestion:target};
 }
 return null;
}
async function reorderTreeItem(type,sourceId,targetId){
 const source=rows(type).find(x=>String(x.id)===String(sourceId)),target=rows(type).find(x=>String(x.id)===String(targetId));
 if(!source||!target||source.id===target.id)return;
 const siblings=dragSiblings(type,source);
 if(!siblings.some(x=>String(x.id)===String(target.id)))throw new Error(type==="section"?"Déplacez la section dans sa page actuelle.":type==="question"?"Déplacez la question dans sa section actuelle.":"Déplacement impossible.");
 const ordered=[...siblings].sort((a,b)=>(Number(a.Ordre)||0)-(Number(b.Ordre)||0)||Number(a.id)-Number(b.id));
 const from=ordered.findIndex(x=>String(x.id)===String(source.id)),to=ordered.findIndex(x=>String(x.id)===String(target.id));
 if(from<0||to<0||from===to)return;
 const [moved]=ordered.splice(from,1);ordered.splice(to,0,moved);
 const table=tableFor(type),actions=[];
 ordered.forEach((r,i)=>{const order=i+1;if(Number(r.Ordre)!==order)actions.push(["UpdateRecord",table,Number(r.id),{Ordre:order}])});
 if(!actions.length)return;
 await applyDesignerActions(actions);await finishTreeMove(type,source.id,"Ordre mis à jour.");
}
