function bindColorFields(scope=document){scope.querySelectorAll("[data-color-picker]").forEach(p=>p.oninput=()=>{const i=scope.querySelector(`[name="${p.dataset.colorPicker}"]`);if(i)i.value=p.value});scope.querySelectorAll("[data-clear-color]").forEach(b=>b.onclick=()=>{const i=scope.querySelector(`[name="${b.dataset.clearColor}"]`);if(i)i.value=""})}
const TYPES=[["Texte","Texte court"],["Texte long","Texte long"],["Description","Texte / Description (sans réponse)"],["Sommaire","Sommaire (sans réponse)"],["Indicateurs","Indicateurs / statistiques (sans réponse)"],["Nombre","Nombre"],["Montant","Montant"],["Date","Date"],["Email","Adresse e-mail"],["Radio","Choix unique (boutons radio)"],["Liste déroulante","Liste déroulante"],["Cases à cocher","Choix multiples (cases à cocher)"],["Matrice_radio","Matrice — choix unique"],["Matrice_checkbox","Matrice — choix multiple"],["Matrice_nombre","Matrice — nombres"],["Matrice_texte","Matrice — texte"],["Tableau_donnees","Tableau de données (lecture seule)"]];
