 if(qsel&&csel)qsel.onchange=()=>{const q=completionBadgeQuestions(type,row).find(x=>codeOf(x.Question_Code)===qsel.value);const choices=q?choicesFor(q):[];csel.innerHTML='<option value="">— Choisir une réponse —</option>'+choices.map(c=>`<option value="${esc(codeOf(c.Choix_Code))}">${esc(first(c,["Libelle","Libellé","Valeur","Choix_Code"],codeOf(c.Choix_Code)))}</option>`).join("");};
