// Contrôle facultatif des boutons de navigation, sans altérer les réglages existants.
function pageNavigationButtonsValue(row){const v=String(row?.Navigation_boutons??"both").trim().toLowerCase();return ["both","previous","next","none"].includes(v)?v:"both";}
async function ensurePageNavigationButtonsColumn(){
 const page=(S.data.PAGES||[])[0];
 // Dans une table vide, la colonne peut déjà exister : tenter la lecture du schéma Grist.
 let hasColumn=page&&Object.prototype.hasOwnProperty.call(page,"Navigation_boutons");
 if(!hasColumn){
  const columns=await grist.docApi.fetchTable("_grist_Tables_column").catch(()=>null);
  const tables=await grist.docApi.fetchTable("_grist_Tables").catch(()=>null);
  if(columns&&tables){const trs=rowsFromTable(tables),crs=rowsFromTable(columns),t=trs.find(x=>x.tableId==="PAGES");hasColumn=!!(t&&crs.some(c=>Number(c.parentId)===Number(t.id)&&c.colId==="Navigation_boutons"));}
 }
 if(!hasColumn){await applyDesignerActions([["AddColumn","PAGES","Navigation_boutons",{type:"Text"}]]);await reload();}
 const fresh=await grist.docApi.fetchTable("PAGES");
 if(!Object.prototype.hasOwnProperty.call(fresh,"Navigation_boutons"))throw new Error("La colonne PAGES.Navigation_boutons est absente ou inaccessible. Créez une colonne Texte nommée exactement Navigation_boutons, puis réessayez.");
}
