function eligibleSourceQuestions(target,excludeTarget=true){
 const all=current().questions;
 if(S.selected?.type==="fiche"){
  const parent=isSubFiche(target)?(S.data.TYPES_FICHES||[]).find(f=>codeOf(f.TypeFiche_Code)===ficheParentCode(target)):null;
  const pc=parent?codeOf(parent.TypeFiche_Code):"";
  return all.filter(q=>!isMatrixLine(q)&&(!ref(q.TypeFiche_Code,S.data.TYPES_FICHES,"TypeFiche_Code")||(pc&&ref(q.TypeFiche_Code,S.data.TYPES_FICHES,"TypeFiche_Code")===pc)));
 }
 return excludeTarget?all.filter(q=>String(q.id)!==String(target?.id)):all;
}
