 const msg=`Cette question est encore référencée par ${details.length>1?"des conditions orphelines":"une condition orpheline"}, qui n’est plus rattachée à aucun élément du questionnaire :\n\n${details.map(x=>`• ${x}`).join("\n")}\n\nNettoyer ${details.length>1?"ces dépendances orphelines":"cette dépendance orpheline"} puis poursuivre la suppression ?`;
 if(!confirm(msg))return false;
 const actions=[];
 for(const c of conds){for(const r of rulesForCondition(c))actions.push(["RemoveRecord","REGLES_CONDITION",Number(r.id)]);actions.push(["RemoveRecord","CONDITIONS",Number(c.id)])}
