 const name=label(row,type);if(!confirm(`Supprimer définitivement « ${name} » ?`))return;const actions=[];
 if(type==="question"){for(const child of questionChildren(row).filter(isMatrixLine))actions.push(["RemoveRecord","QUESTIONS",Number(child.id)]);const conds=ownedConditionsForQuestion(row);for(const c of conds)for(const r of rulesForCondition(c))actions.push(["RemoveRecord","REGLES_CONDITION",Number(r.id)]);for(const f of choiceFiltersFor(row))actions.push(["RemoveRecord","FILTRES_CHOIX",Number(f.id)]);for(const c of choicesFor(row))actions.push(["RemoveRecord","CHOIX_QUESTIONS",Number(c.id)]);for(const c of matrixColumns(row))actions.push(["RemoveRecord","COLONNES_MATRICE",Number(c.id)]);for(const c of conds)actions.push(["RemoveRecord","CONDITIONS",Number(c.id)])}
