function responseRefMatches(raw,response){
  const v=codeOf(raw),rc=codeOf(response?.Reponse_Code);
  return String(v)===String(response?.id)||String(v)===String(rc);
}
async function removeResponseCascade(response){
  if(!response?.id)return;
  const [elements,values,selections]=await Promise.all([
    fetchOptionalTable("ELEMENTS_REPONSE"),
    fetchOptionalTable("VALEURS_REPONSE"),
    fetchOptionalTable("SELECTIONS_REPONSE")
  ]);
  const els=elements.filter(e=>responseRefMatches(e.Reponse_Code,response));
  const elIds=new Set(els.map(e=>String(e.id)));
  const elCodes=new Set(els.map(e=>String(codeOf(e.Element_Code))));
  const vals=values.filter(v=>{
    const raw=codeOf(v.Element_Code);
    return elIds.has(String(raw))||elCodes.has(String(raw));
  });
  const valIds=new Set(vals.map(v=>String(v.id)));
  const valCodes=new Set(vals.map(v=>String(codeOf(v.Valeur_Code))));
  const sels=selections.filter(s=>{
    const raw=codeOf(s.Valeur_Code);
    return valIds.has(String(raw))||valCodes.has(String(raw));
  });
  const actions=[];
  for(const s of sels)actions.push(["RemoveRecord","SELECTIONS_REPONSE",Number(s.id)]);
  for(const v of vals)actions.push(["RemoveRecord","VALEURS_REPONSE",Number(v.id)]);
  for(const e of els)actions.push(["RemoveRecord","ELEMENTS_REPONSE",Number(e.id)]);
  actions.push(["RemoveRecord","REPONSES",Number(response.id)]);
  if(actions.length)await applyDesignerActions(actions);
}
async function refreshResultsAfterReset(){
  await reload();
  const campaigns=campaignVersionRows();
  const responsesAll=await fetchOptionalTable("REPONSES");
  const elements=await fetchOptionalTable("ELEMENTS_REPONSE");
  const values=await fetchOptionalTable("VALEURS_REPONSE");
  const selections=await fetchOptionalTable("SELECTIONS_REPONSE");
  S.resultsExportData={responsesAll,elements,values,selections};
  renderResults({campaigns,responses:responsesAll});
}
async function resetSingleResponse(response,labelText="cette réponse"){
  if(!response?.id)return;
  if(!confirm(`Réinitialiser ${labelText} ?\n\nToutes les réponses saisies seront supprimées. Le participant, la campagne et son lien seront conservés.`))return;
  try{
    await removeResponseCascade(response);
    await refreshResultsAfterReset();
    status("Réponse réinitialisée.",false,true);
  }catch(e){
    console.error("Réinitialisation réponse",e);
    const msg=`Réinitialisation impossible : ${e?.message||e}`;
    status(msg,true,true);alert(msg);
  }
}
async function resetCampaignResponses(rows,responses){
  const targets=(responses||[]).filter(r=>rows.some(c=>responseMatchesCampaign(r,c)));
  if(!targets.length){alert("Cette campagne ne contient aucune réponse à réinitialiser.");return;}
  const confirmation=prompt(`ATTENTION : ${targets.length} réponse(s) vont être supprimée(s) définitivement.\n\nLes participants, la campagne et les liens seront conservés.\n\nTapez REINITIALISER pour confirmer.`);
  if(String(confirmation||"").trim().toUpperCase()!=="REINITIALISER")return;
  try{
    for(const r of targets)await removeResponseCascade(r);
    await refreshResultsAfterReset();
    status(`${targets.length} réponse(s) réinitialisée(s).`,false,true);
  }catch(e){
    console.error("Réinitialisation campagne",e);
    const msg=`Réinitialisation globale impossible : ${e?.message||e}`;
    status(msg,true,true);alert(msg);
  }
}

