function wordAnswerMarkup(q){const t=questionType(q).toLowerCase(),choices=choicesFor(q);if(t==="description")return"";if(t==="sommaire")return'<div class="note">Sommaire du questionnaire</div>';if(isMatrixQuestion(q)){const lines=matrixLines(q),cols=(t==="matrice_radio"||t==="matrice_checkbox")?choices.map(wordChoiceLabel):matrixColumns(q).map(c=>first(c,["Libelle","Libellé","Nom","Titre","ColonneMatrice_Code"],codeOf(c.ColonneMatrice_Code)||""));let h='<table class="matrix"><tr><th></th>'+cols.map(c=>`<th>${wordText(c)}</th>`).join("")+'</tr>';for(const l of lines)h+=`<tr><th>${wordText(label(l,"question"))}</th>${cols.map(()=>`<td>${t==="matrice_radio"?'○':t==="matrice_checkbox"?'☐':'&nbsp;'}</td>`).join("")}</tr>`;return h+'</table>'}if((t.includes("liste")||t.includes("déroul")||t.includes("deroul"))&&isTrue(q?.Selection_multiple)){const vals=choices.length?choices.map(wordChoiceLabel):wordReferentialValues(q);return vals.length?`<div class="choices">${vals.map(x=>`☐ ${wordText(x)}`).join("<br>")}</div>`:'<div class="answer">&nbsp;</div>'}if(t.includes("radio")||t.includes("liste")){const vals=choices.length?choices.map(wordChoiceLabel):wordReferentialValues(q);return vals.length?`<div class="choices">${vals.map(x=>`○ ${wordText(x)}`).join("<br>")}</div>`:'<div class="answer">&nbsp;</div>'}if(t.includes("case")||t.includes("checkbox")){const vals=choices.length?choices.map(wordChoiceLabel):wordReferentialValues(q);return vals.length?`<div class="choices">${vals.map(x=>`☐ ${wordText(x)}`).join("<br>")}</div>`:'<div class="answer">&nbsp;</div>'}if(t==="tableau_donnees")return'<div class="note">Tableau de données en lecture seule (contenu alimenté depuis Grist).</div>';return'<div class="answer">&nbsp;</div>'}
function wordQuestionBlock(q){const kind=displayBlockKind(q),help=wordQuestionHelp(q);if(kind==="description")return`<div class="description">${wordText(label(q,"question"))}${help?`<div>${wordText(help)}</div>`:""}</div>`;if(kind==="toc")return`<div class="description"><strong>${wordText(label(q,"question")||"Sommaire")}</strong><div class="note">Sommaire du questionnaire</div></div>`;return`<div class="question"><div class="qhead"><span class="qcode">${wordText(wordQuestionCode(q))}</span><strong>${wordText(label(q,"question"))}${wordRequired(q)?' <span class="required">*</span>':""}</strong></div>${help?`<div class="help">${wordText(help)}</div>`:""}<div class="qtype">Type : ${wordText(questionType(q)||"Question")}</div>${wordAnswerMarkup(q)}<div class="remarks"><strong>Remarques :</strong><br>&nbsp;<br>&nbsp;</div></div>`}
function wordFicheBlock(f,sectionQuestions){const fc=codeOf(f.TypeFiche_Code),qs=sectionQuestions.filter(q=>!isMatrixLine(q)&&ref(q.TypeFiche_Code,S.data.TYPES_FICHES,"TypeFiche_Code")===fc);let h=`<div class="fiche"><h4>${isSubFiche(f)?"Sous-fiche":"Fiche"} : ${wordText(label(f,"fiche"))}</h4>`;for(const q of qs)h+=wordQuestionBlock(q);for(const sf of (S.data.TYPES_FICHES||[]).filter(x=>active(x)&&vm(x)&&ficheParentCode(x)===fc))h+=wordFicheBlock(sf,sectionQuestions);return h+'</div>'}
function buildQuestionnaireWordHtml(){const q=questionnaireRow(),v=versionRow();if(!q||!v)throw new Error("Sélectionnez d’abord un questionnaire et une version.");const {pages,sections,questions,fiches}=current(),title=first(v,["Titre","Titre_affiche","Nom"],label(q,"questionnaire")),intro=first(v,["Introduction","Texte_introduction"],""),footer=first(v,["Pied_de_page","Pied_page","Footer"],"");let body=`<h1>${wordText(title)}</h1><div class="meta"><strong>Questionnaire :</strong> ${wordText(label(q,"questionnaire"))}<br><strong>Version :</strong> ${wordText(label(v,"version"))}<br><strong>Document de relecture généré le :</strong> ${new Date().toLocaleDateString("fr-FR")}</div>${intro?`<div class="intro">${wordText(intro)}</div>`:""}<div class="review-note"><strong>Document de relecture</strong><br>Vous pouvez saisir vos remarques directement dans les zones prévues sous chaque question ou utiliser les commentaires et le suivi des modifications de Word.</div>`;for(const p of pages){const pc=codeOf(p.Page_Code);body+=`<div class="page"><h2>${wordText(label(p,"page"))}</h2>`;for(const sec of sections.filter(x=>ref(x.Page_Code,S.data.PAGES,"Page_Code")===pc)){const sc=codeOf(sec.Section_Code),sq=questions.filter(x=>ref(x.Section_Code,S.data.SECTIONS,"Section_Code")===sc);body+=`<div class="section"><h3>${wordText(label(sec,"section"))}</h3>`;for(const x of sq.filter(x=>!isMatrixLine(x)&&!ref(x.TypeFiche_Code,fiches,"TypeFiche_Code")))body+=wordQuestionBlock(x);const used=new Set(sq.map(x=>ref(x.TypeFiche_Code,fiches,"TypeFiche_Code")).filter(Boolean));for(const f of fiches.filter(f=>!isSubFiche(f)&&(used.has(codeOf(f.TypeFiche_Code))||fiches.some(sf=>ficheParentCode(sf)===codeOf(f.TypeFiche_Code)&&used.has(codeOf(sf.TypeFiche_Code))))))body+=wordFicheBlock(f,sq);body+='</div>'}body+='</div>'}if(footer)body+=`<div class="footer">${wordText(footer)}</div>`;return`<!DOCTYPE html><html><head><meta charset="utf-8"><title>${wordText(title)}</title><style>@page{size:A4;margin:1.6cm}body{font-family:Arial,sans-serif;font-size:10.5pt;line-height:1.35;color:#222}h1{font-size:22pt;margin:0 0 12pt}h2{font-size:17pt;border-bottom:2px solid #555;padding-bottom:4pt;margin-top:24pt;page-break-after:avoid}h3{font-size:13.5pt;margin:18pt 0 8pt;page-break-after:avoid}h4{font-size:11.5pt;margin:12pt 0 6pt}.meta,.intro,.review-note{margin:10pt 0;padding:9pt;border:1px solid #bbb}.review-note{background:#f3f3f3}.question{border:1px solid #ccc;padding:9pt;margin:8pt 0;page-break-inside:avoid;break-inside:avoid}.qhead{font-size:11pt;page-break-after:avoid;break-after:avoid}.qcode{float:right;color:#777;font-size:8.5pt;font-weight:normal}.required{color:#a00}.help,.qtype,.note{color:#666;font-size:9pt;margin-top:4pt;page-break-after:avoid;break-after:avoid}.choices{margin:7pt 0 4pt 12pt;page-break-inside:avoid;break-inside:avoid}.answer{height:20pt;border-bottom:1px solid #999;margin:7pt 0;page-break-inside:avoid;break-inside:avoid}.remarks{margin-top:9pt;padding:6pt;border-top:1px dashed #aaa;color:#555;min-height:28pt;page-break-inside:avoid;break-inside:avoid}.description{margin:9pt 0;padding:7pt;background:#f7f7f7}.fiche{margin:10pt 0 10pt 10pt;padding-left:9pt;border-left:3px solid #aaa;page-break-inside:auto;break-inside:auto}.fiche h4{page-break-after:avoid;break-after:avoid}.matrix{border-collapse:collapse;width:100%;margin:8pt 0;font-size:9pt;page-break-inside:auto;break-inside:auto}.matrix tr{page-break-inside:avoid;break-inside:avoid}.matrix th,.matrix td{border:1px solid #999;padding:4pt;text-align:center}.matrix th:first-child{text-align:left}.footer{margin-top:24pt;padding-top:8pt;border-top:1px solid #aaa;color:#666;font-size:9pt}</style></head><body>${body}</body></html>`}
function exportQuestionnaireWord(){try{const html=buildQuestionnaireWordHtml(),blob=new Blob(["\ufeff",html],{type:"application/msword;charset=utf-8"}),name=`Questionnaire_${safeVar(label(questionnaireRow(),"questionnaire"))}_${safeVar(label(versionRow(),"version"))}.doc`;downloadBlob(blob,name);status("Document Word de relecture généré.",false,true)}catch(e){console.error("Export Word questionnaire",e);status(`Export Word impossible : ${e?.message||e}`,true,true);alert(`Export Word impossible : ${e?.message||e}`)}}
